import { Suspense } from 'react'
import { CardStats } from './CardStats'
import { LatestInvoices } from './LatestInvoices'
import { RevenueChart } from './RevenueChart'
import { getDashboardData } from './dashboard-data'
import {
  CardStatsSkeleton,
  LatestInvoicesSkeleton,
  RevenueChartSkeleton,
} from './skeletons'

async function CardStatsSection() {
  const data = await getDashboardData()
  return (
    <CardStats
      totalRevenue={data.totalRevenue}
      totalInvoices={data.totalInvoices}
    />
  )
}

async function RevenueChartSection() {
  const data = await getDashboardData()
  return <RevenueChart revenue={data.revenue} />
}

async function LatestInvoicesSection() {
  const data = await getDashboardData()
  return <LatestInvoices invoices={data.invoices} />
}

export default function Page() {
  return (
    <main>
      <h1>Dashboard</h1>
      <Suspense fallback={<CardStatsSkeleton />}>
        <CardStatsSection />
      </Suspense>
      <Suspense fallback={<RevenueChartSkeleton />}>
        <RevenueChartSection />
      </Suspense>
      <Suspense fallback={<LatestInvoicesSkeleton />}>
        <LatestInvoicesSection />
      </Suspense>
    </main>
  )
}

